!> Performs the matrix-matrix operation `C = alpha*op(A)*op(B) + beta*C`, where `op(X)` is either `op(X) = X` or `op(X) = X^T`, `alpha` and `beta` are scalars, `A`, `B`, and `C` are matrices, with `op(A)` an `M`-by-`K` matrix, `op(B)` a `K`-by-`N` matrix, and `C` an `M`-by-`N` matrix.
!
! ## Notes
!
! * Modified version of reference BLAS routine (version 3.12.0). Updated to "free form" Fortran 95.
!
! ## Authors
!
! * Univ. of Tennessee
! * Univ. of California Berkeley
! * Univ. of Colorado Denver
! * NAG Ltd.
!
! ## History
!
! * Written on 8-February-1989.
!
!   - Jack Dongarra, Argonne National Lab.
!   - Iain Duff, AERE Harwell.
!   - Jeremy Du Croz, Numerical Algorithms Group Ltd.
!   - Sven Hammarling, Numerical Algorithms Group Ltd.
!
! ## License
!
! From <http://netlib.org/blas/faq.html>:
!
! > The reference BLAS is a freely-available software package. It is available from netlib via anonymous ftp and the World Wide Web. Thus, it can be included in commercial software packages (and has been). We only ask that proper credit be given to the authors.
! >
! > Like all software, it is copyrighted. It is not trademarked, but we do ask the following:
! >
! > * If you modify the source for these routines we ask that you change the name of the routine and comment the changes made to the original.
! >
! > * We will gladly answer any questions regarding the software. If a modification is done, however, it is the responsibility of the person who modified the routine to provide support.
!
! @param {character} transA - specifies whether `A` is transposed (`T` or `C`) or not transposed (`N`)
! @param {character} transB - specifies whether `B` is transposed (`T` or `C`) or not transposed (`N`)
! @param {integer} M - number of rows in `op(A)` and `C`
! @param {integer} N - number of columns in `op(B)` and `C`
! @param {integer} K - number of columns in `op(A)` and rows in `op(B)`
! @param {double} alpha - scalar constant
! @param {Array<double>} A - first matrix
! @param {integer} LDA - leading dimension of `A`
! @param {Array<double>} B - second matrix
! @param {integer} LDB - leading dimension of `B`
! @param {double} beta - scalar constant
! @param {Array<double>} C - result matrix
! @param {integer} LDC - leading dimension of `C`
!<
subroutine dgemm( transA, transB, M, N, K, alpha, A, LDA, B, LDB, beta, C, LDC )
  implicit none
  ! ..
  ! Internal parameters:
  integer, parameter :: dp = kind(0.0d0) ! double-precision
  ! ..
  ! Scalar arguments:
  character(len=1) :: transA, transB
  real(dp) :: alpha, beta
  integer :: M, N, K, LDA, LDB, LDC
  ! ..
  ! Array arguments:
  real(dp) :: A(LDA,*), B(LDB,*), C(LDC,*)
  ! ..
  ! Local scalars:
  real(dp) :: temp
  integer :: i, info, j, l, nrowa, nrowb
  logical :: nota, notb
  ! ..
  ! External functions:
  interface
    subroutine xerbla( srname, info )
      character*(*) :: srname
      integer :: info
    end subroutine xerbla
  end interface
  ! ..
  ! Intrinsic functions:
  intrinsic max
  ! ..
  ! Test whether `op(A)` is transposed...
  nota = ( transA == 'N' .OR. transA == 'n' )
  ! ..
  ! Test whether `op(B)` is transposed...
  notb = ( transB == 'N' .OR. transB == 'n' )
  ! ..
  ! Set `nrowa` to the number of rows of `A` as stored (before transposing)...
  if ( nota ) then
    nrowa = M
  else
    nrowa = K
  end if
  ! ..
  ! Set `nrowb` to the number of rows of `B` as stored (before transposing)...
  if ( notb ) then
    nrowb = K
  else
    nrowb = N
  end if
  ! ..
  ! Validate input arguments...
  info = 0
  if ( .NOT. nota .AND. transA /= 'T' .AND. transA /= 't' .AND. transA /= 'C' .AND. transA /= 'c' ) then
    info = 1
  else if ( .NOT. notb .AND. transB /= 'T' .AND. transB /= 't' .AND. transB /= 'C' .AND. transB /= 'c' ) then
    info = 2
  else if ( M < 0 ) then
    info = 3
  else if ( N < 0 ) then
    info = 4
  else if ( K < 0 ) then
    info = 5
  else if ( LDA < max( 1, nrowa ) ) then
    info = 8
  else if ( LDB < max( 1, nrowb ) ) then
    info = 10
  else if ( LDC < max( 1, M ) ) then
    info = 13
  end if
  if ( info /= 0 ) then
    call xerbla( 'dgemm ', info )
    return
  end if
  ! ..
  ! Quick return if possible...
  if ( M == 0 .OR. N == 0 .OR. ( ( alpha == 0.0d0 .OR. K == 0 ) .AND. beta == 1.0d0 ) ) then
    return
  end if
  ! ..
  ! Handle the case where `alpha` is zero...
  if ( alpha == 0.0d0 ) then
    if ( beta == 0.0d0 ) then
      do j = 1, N
        do i = 1, M
          C( i, j ) = 0.0d0
        end do
      end do
    else
      do j = 1, N
        do i = 1, M
          C( i, j ) = beta * C( i, j )
        end do
      end do
    end if
    return
  end if
  ! ..
  ! Perform matrix multiplication...
  if ( notb ) then
    if ( nota ) then
      ! Form C = alpha*A*B + beta*C
      do j = 1, N
        if ( beta == 0.0d0 ) then
          do i = 1, M
            C( i, j ) = 0.0d0
          end do
        else if ( beta /= 1.0d0 ) then
          do i = 1, M
            C( i, j ) = beta * C( i, j )
          end do
        end if
        do l = 1, K
          temp = alpha * B( l, j )
          do i = 1, M
            C( i, j ) = C( i, j ) + temp * A( i, l )
          end do
        end do
      end do
    else
      ! Form C = alpha*A^T*B + beta*C
      do j = 1, N
        do i = 1, M
          temp = 0.0d0
          do l = 1, K
            temp = temp + A( l, i ) * B( l, j )
          end do
          if ( beta == 0.0d0 ) then
            C( i, j ) = alpha * temp
          else
            C( i, j ) = alpha * temp + beta * C( i, j )
          end if
        end do
      end do
    end if
  else
    if ( nota ) then
      ! Form C = alpha*A*B^T + beta*C
      do j = 1, N
        if ( beta == 0.0d0 ) then
          do i = 1, M
            C( i, j ) = 0.0d0
          end do
        else if ( beta /= 1.0d0 ) then
          do i = 1, M
            C( i, j ) = beta * C( i, j )
          end do
        end if
        do l = 1, K
          temp = alpha * B( j, l )
          do i = 1, M
            C( i, j ) = C( i, j ) + temp * A( i, l )
          end do
        end do
      end do
    else
      ! Form C = alpha*A^T*B^T + beta*C
      do j = 1, N
        do i = 1, M
          temp = 0.0d0
          do l = 1, K
            temp = temp + A( l, i ) * B( j, l )
          end do
          if ( beta == 0.0d0 ) then
            C( i, j ) = alpha * temp
          else
            C( i, j ) = alpha * temp + beta * C( i, j )
          end if
        end do
      end do
    end if
  end if
  return
end subroutine dgemm
